    """Each nonzero cell becomes a factor x factor block holding the input pattern with its color and background swapped; zero cells become empty blocks."""
    h, w = len(grid), len(grid[0])
    out = [[0] * (w * factor) for _ in range(h * factor)]
    for i in range(h):
        for j in range(w):
            v = grid[i][j]
            if v == 0:
                continue
            for r in range(h):
                for c in range(w):
                    out[i * factor + r][j * factor + c] = 0 if grid[r][c] != 0 else v
    return out
